const areaCounts = {}
const output = places.map((p, idx) => {
  areaCounts[p.area] = (areaCounts[p.area] ?? 0) + 1
  const tags = Array.from(new Set([
    ...(p.coffeeStyles.includes('Specialty Coffee') ? ['Specialty'] : []),
    ...p.tags,
    p.placeType,
  ]))
  return {
    id: `place-${String(idx + 1).padStart(3, '0')}`,
    name: p.name,
    area: p.area,
    address: p.address,
    addressVerified: p.addressVerified,
    latitude: p.lat,
    longitude: p.lng,
    description: p.description,
    shortDescription: p.shortDescription,
    placeType: p.placeType,
    priceRange: p.price,
    rating: p.rating,
    reviewCount: p.reviews,
    website: p.website,
    instagram: p.instagram,
    twitter: p.twitter,
    email: p.email,
    phone: p.phone,
    openingHours: {
      'Mon – Fri': `${p.openHour > 12 ? p.openHour - 12 : p.openHour}:00 ${p.openHour >= 12 ? 'PM' : 'AM'} – ${p.closeHour > 12 ? p.closeHour - 12 : p.closeHour}:00 ${p.closeHour >= 12 ? 'PM' : 'AM'}`,
      'Sat – Sun': `${p.openHour > 12 ? p.openHour - 12 : p.openHour}:00 ${p.openHour >= 12 ? 'PM' : 'AM'} – ${(p.closeHour + 1) > 24 ? 24 : (p.closeHour + 1) > 12 ? (p.closeHour + 1) - 12 : (p.closeHour + 1)}:00 ${(p.closeHour + 1) >= 12 ? 'PM' : 'AM'}`,
    },
    tags,
    coffeeStyles: p.coffeeStyles,
    amenities: p.amenities,
    bestFor: p.bestFor,
    signatureDrinks: p.signatureDrinks,
    roaster: p.roaster,
    origin: p.origin,
    image: p.image,
    imageVerified: p.imageVerified,
    hasFood: p.hasFood,
    petFriendly: p.petFriendly,
    openNowHint: { open: p.openHour, close: p.closeHour },
    whyGo: p.whyGo,
  }
})

// Photo/contact overrides sourced programmatically (e.g. via the Google Places API,
// see scripts/fetch-google-photos.mjs) live in a separate JSON file, keyed by exact
// place name, so this script's hand-curated `places` array stays the single source
// of truth for everything else while still picking up verified enrichment.
const overridesPath = new URL('./photo-overrides.json', import.meta.url)
const overrides = fs.existsSync(overridesPath)
  ? JSON.parse(fs.readFileSync(overridesPath, 'utf-8'))
  : {}
for (const place of output) {
  const override = overrides[place.name]
  if (override) Object.assign(place, override)
}

fs.writeFileSync(new URL('../src/data/places.json', import.meta.url), JSON.stringify(output, null, 2))
const verifiedCount = output.filter((p) => p.addressVerified).length
const imageVerifiedCount = output.filter((p) => p.imageVerified).length
console.log('Wrote', output.length, 'places across', Object.keys(areaCounts).length, 'areas')
console.log(verifiedCount, 'have a fully verified street address;', output.length - verifiedCount, 'are neighbourhood-level pending confirmation')
console.log(imageVerifiedCount, 'have a confirmed photo of the actual venue;', output.length - imageVerifiedCount, 'use representative stock photography')
console.log(areaCounts)
